using Newtonsoft.Json;

namespace Zentin.Payment.SDK.Models
{
    /// <summary>
    /// Refund order creation response entity class
    /// </summary>
    public class RefundOrderCreateResModel : AgPayObject
    {
        /// <summary>
        /// Refund order number (generated by gateway)
        /// </summary>
        [JsonProperty("refundOrderId")]
        public string RefundOrderId { get; set; }

        /// <summary>
        /// Merchant initiated refund order number
        /// </summary>
        [JsonProperty("mchRefundNo")]
        public string MchRefundNo { get; set; }

        /// <summary>
        /// Order payment amount
        /// </summary>
        [JsonProperty("payAmount")]
        public long PayAmount { get; set; }

        /// <summary>
        /// Requested refund amount
        /// </summary>
        [JsonProperty("refundAmount")]
        public long RefundAmount { get; set; }

        /// <summary>
        /// Refund status
        /// 0-Order created
        /// 1-Refunding
        /// 2-Refund successful
        /// 3-Refund failed
        /// 4-Refund closed
        /// </summary>
        [JsonProperty("state")]
        public int State { get; set; }

        /// <summary>
        /// Channel refund order number
        /// </summary>
        [JsonProperty("channelOrderNo")]
        public string ChannelOrderNo { get; set; }

        /// <summary>
        /// Payment channel error code
        /// </summary>
        [JsonProperty("errCode")]
        public string ErrCode { get; set; }

        /// <summary>
        /// Payment channel error message
        /// </summary>
        [JsonProperty("errMsg")]
        public string ErrMsg { get; set; }
    }
}